stream = sys.stdin.buffer if args.file == "-" else open(args.file, "rb")
try:
    # determine how far the skip can actually advance (clamped to EOF)
    try:
        stream.seek(0, 2)
        size = stream.tell()
    except OSError:
        size = None
    start = args.skip if size is None else min(max(args.skip, 0), size)
    if size is not None:
        stream.seek(start)
        raw = stream.read()
    else:
        # not seekable (e.g. pipe): discard SKIP bytes manually
        remaining = args.skip
        while remaining > 0:
            chunk = stream.read(min(remaining, 65536))
            if not chunk:
                break
            remaining -= len(chunk)
        start = args.skip - remaining
        raw = stream.read()
finally:
    if stream is not sys.stdin.buffer:
        stream.close()

end = start + len(raw)  # offset hexdump would report at EOF
data = raw if args.length is None else raw[:max(0, args.length)]

lines = []
